const item = items[0];

const rawBody = item.json.textPlain || item.json.textHtml || "";
const cleanBody = rawBody.replace(/\s+/g, ' ').trim();
const truncatedBody = cleanBody.length > 500 ? cleanBody.substring(0, 500) + "..." : cleanBody;

return {
  json: {
    ...item.json,
    original_body: truncatedBody
  }
};

let parsedData = {};
try {
  const item = items[0];
  const rawContent = item.json.choices[0].message.content;
  parsedData = JSON.parse(rawContent);
} catch (error) {
  parsedData = {
    category: "manual_review",
    urgency: 3,
    property_reference: "",
    suggested_reply: "Dear Customer,\n\nWe have received your request and our team is reviewing it.\n\nBest regards,\nProperty Support Team",
    parsing_error: true
  };
}

const urgencyMap = {
  1: 'Low',
  2: 'Low',
  3: 'Medium',
  4: 'High',
  5: 'Critical'
};
const urgencyLabel = urgencyMap[parsedData.urgency] || 'Medium';

const validCategories = ["Maintenance", "Tenant Query", "Viewing", "Enquiry", "Spam"];
const finalCategory = validCategories.includes(parsedData.category) ? parsedData.category : "manual_review";

const finalReply = (finalCategory === "Spam")
  ? "N/A — No reply generated for spam."
  : (parsedData.suggested_reply || "Thank you for reaching out. We are looking into your issue.");

let rawSender = "user@example.com";
try {
  const imapNode = $('When Email Received via IMAP').item.json;
  if (imapNode.from?.value?.[0]?.address) {
    const fromData = imapNode.from.value[0];
    rawSender = fromData.name ? `${fromData.name} <${fromData.address}>` : fromData.address;
  } else if (imapNode.from?.address) {
    rawSender = imapNode.from.address;
  } else if (typeof imapNode.from === 'string') {
    rawSender = imapNode.from;
  }
} catch (e) {
}

let cleanEmail = "user@example.com";
let cleanName = "Unknown";

const angleBracketMatch = rawSender.match(/(.*?)\s*<([^>]+)>/);
if (angleBracketMatch) {
  cleanName = angleBracketMatch[1].replace(/["']/g, "").trim() || "Unknown";
  cleanEmail = angleBracketMatch[2].trim().toLowerCase();
} else {
  const emailRegex = /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/;
  const match = rawSender.match(emailRegex);
  if (match) {
    cleanEmail = match[0].trim().toLowerCase();
  }
}

let originalSubject = "No Subject";
let originalBody = "Empty Body";
try {
  originalSubject = $('When Email Received via IMAP').item.json.subject || "No Subject";
  originalBody = $('Cleanse Email Content').item.json.original_body || "Empty Body";
} catch(e) {}

return {
  json: {
    category: finalCategory,
    urgency: urgencyLabel,
    property_reference: parsedData.property_reference || "",
    suggested_reply: finalReply,
    original_subject: originalSubject,
    original_body: originalBody,
    sender_name: cleanName,
    sender_email: cleanEmail
  }
};

const errorItem = items[0];
const errorMsg = errorItem.json.error || errorItem.json.message || "Unknown API error";

return [{
  json: {
    category: "manual_review",
    urgency: "Medium",
    property_reference: "",
    suggested_reply: `System error: ${errorMsg}. Please handle manually.`,
    original_subject: errorItem.json.original_subject || "Error Subject",
    original_body: errorItem.json.original_body || "Error Body",
    sender_name: "System Alert",
    sender_email: "user@example.com",
    error_alert: errorMsg
  }
}];

